param([ValidateSet('Compile', 'Red', 'Race', 'Vet', 'Lint', 'Format')][string]$Gate)
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot '212-go-env.ps1')
$env:TEMP = Join-Path (Get-Location) 'bin\m14t'
$env:TMP = $env:TEMP
[IO.Directory]::CreateDirectory($env:TEMP) | Out-Null
$go = Join-Path $env:GOROOT 'bin\go.exe'
switch ($Gate) {
    'Compile' { $exe = $go; $arguments = @('test', '-run=^$', '-count=1', './...') }
    'Red' { $exe = $go; $arguments = @('test', '-count=1', '-timeout=30m', '-json', '-run', '^TestU1g_', './internal/core') }
    'Race' { $exe = $go; $arguments = @('test', '-count=1', '-race', '-timeout=30m', '-json', '-run', '^TestU1g_', './internal/core') }
    'Vet' { $exe = $go; $arguments = @('vet', './internal/core/...') }
    'Lint' { $exe = Join-Path (Get-Location) 'bin\golangci-lint.exe'; $arguments = @('run', '--timeout=5m', '--out-format=json', './internal/core/...') }
    'Format' { $exe = Join-Path $env:GOROOT 'bin\gofmt.exe'; $arguments = @('-l', 'internal/core/shipment_p1_lifecycle_remediation_test.go') }
}
$before = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ')
$output = @(& $exe @arguments 2>&1 | ForEach-Object { "$_" })
$native = $LASTEXITCODE
$events = @()
if ($Gate -in @('Red', 'Race')) {
    foreach ($line in $output) {
        try {
            $row = $line | ConvertFrom-Json
            if ($row.Test -and $row.Action -in @('pass', 'fail', 'skip')) {
                $events += [ordered]@{ test = $row.Test; action = $row.Action }
            }
        } catch { }
    }
}
$proof = [ordered]@{
    task = '211.013-T'
    gate = $Gate
    started_at = $before
    finished_at = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ')
    executable = $exe
    arguments = $arguments
    native_exit = $native
    go_version = 'go1.24.0'
    offline = $true
    workspace_temp = $env:TEMP
    test_events = $events
    output = (($output -join "`n") -replace "`r", '')
}
$directory = Join-Path (Get-Location) 'docs\memory\2026-11-07\212-S-M14-harness'
[IO.Directory]::CreateDirectory($directory) | Out-Null
$path = Join-Path $directory ($Gate.ToLowerInvariant() + '-proof.json')
if (Test-Path $path) { throw 'Proof already exists; no overwrite' }
[IO.File]::WriteAllText($path, (($proof | ConvertTo-Json -Depth 8) -replace "`r`n", "`n") + "`n", [Text.UTF8Encoding]::new($false))
Write-Output (([pscustomobject]$proof | Select-Object task,gate,started_at,finished_at,native_exit,test_events) | ConvertTo-Json -Depth 8 -Compress)
exit $native
